<div class="d-flex flex-wrap justify-content-between align-items-end mb-4"><div><span class="lh-kicker"><?= $admin ? 'Super Admin' : 'Production tracking' ?></span><h1 class="lh-page-title mb-1">Material requests</h1><p class="text-secondary mb-0"><?= $admin ? 'Turn approved event needs into clear production briefs.' : 'Track the production materials requested for your events.' ?></p></div><a class="btn btn-outline-primary" href="/calendar">Back to calendar</a></div><div class="d-grid gap-3"><?php foreach ($requests as $item): ?><a class="lh-card p-4 text-decoration-none" href="/material-requests/<?= (int)$item['id'] ?>"><div class="d-flex flex-wrap justify-content-between gap-3"><div><span class="badge text-bg-light text-uppercase"><?= e(str_replace('_',' ',$item['status'])) ?></span><h2 class="h5 text-dark mt-2 mb-1"><?= e($item['event_title']) ?></h2><div class="small text-secondary"><?= e($item['location']) ?> · <?= e(date('M j, Y', strtotime($item['event_date']))) ?></div></div><div class="text-end"><div class="small text-secondary"><?= $admin ? 'Requester' : 'Deadline' ?></div><div class="fw-semibold text-dark"><?= $admin ? e($item['requester_name']) : e($item['deadline'] ? date('M j, Y', strtotime($item['deadline'])) : 'Not set') ?></div></div></div></a><?php endforeach; if (!$requests): ?><div class="lh-card p-5 text-center text-secondary">No material requests yet.</div><?php endif; ?></div>
